SELECT change_date AS changeDate, old_price AS oldPrice, new_price AS newPrice, changed_by AS changedBy FROM price_change_log WHERE product_name = #{productName}
AND (stock_system = #{system} OR stock_system IS NULL)
ORDER BY change_date ASC, id ASC

SELECT id, old_price AS oldPrice, new_price AS newPrice
FROM price_change_log
WHERE product_name = #{productName}
  AND change_date = #{changeDate}
  AND IFNULL(stock_system, 'central') = #{system}
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE price_change_log
SET new_price = #{newPrice}, changed_by = #{changedBy}
WHERE id = #{id}
